/* 68000 state and operation semantics for the recompiled code.
 *
 * The C code generated by tools/recomp68k/ uses only these definitions: registers in Cpu68k,
 * memory accesses through the bus functions, and one inline function per operation that
 * computes the result and the CCR flags.
 *
 * The semantics are validated instruction by instruction against Musashi (tests/differential/).
 * Behaviour reference: Motorola M68000 Programmer's Reference Manual.
 */
#ifndef CPU68K_H
#define CPU68K_H

#include <stdbool.h>
#include <stdint.h>

typedef struct Cpu68k {
    uint32_t d[8];
    uint32_t a[8];          /* a[7] is the active stack pointer (SSP or USP depending on S) */
    uint32_t pc;
    uint32_t usp, ssp;      /* copy of the inactive stack pointer */
    /* CCR split into fields: each flag is 0 or 1 */
    uint8_t x, n, z, v, c;
    /* rest of the SR: supervisor mode, trace and interrupt mask */
    uint8_t s, t, imask;
    int64_t cycles;         /* 68000 clock cycles consumed */
    uint8_t stopped;       /* STOP executed: waiting for an interrupt */
    /* Interrupt sampling (cycles68k.h): opcode and start cycle of the last executed
     * instruction. */
    uint16_t op;
    int64_t start_cycle;
} Cpu68k;

/* ------------------------------------------------------------------ bus */
/* Implemented by the runtime (or the test harness). 24-bit addresses. */
uint32_t bus_r8(uint32_t a);
uint32_t bus_r16(uint32_t a);
void bus_w8(uint32_t a, uint32_t v);
void bus_w16(uint32_t a, uint32_t v);

static inline uint32_t bus_r32(uint32_t a) { return bus_r16(a) << 16 | bus_r16(a + 2); }
static inline void bus_w32(uint32_t a, uint32_t v) { bus_w16(a, v >> 16); bus_w16(a + 2, v & 0xFFFF); }

/* ------------------------------------------------------------------ SR */
static inline uint32_t cpu_get_sr(const Cpu68k *c)
{
    return (uint32_t)c->t << 15 | (uint32_t)c->s << 13 | (uint32_t)c->imask << 8 |
           (uint32_t)c->x << 4 | (uint32_t)c->n << 3 | (uint32_t)c->z << 2 | (uint32_t)c->v << 1 | c->c;
}

static inline void cpu_set_ccr(Cpu68k *c, uint32_t ccr)
{
    c->x = ccr >> 4 & 1; c->n = ccr >> 3 & 1; c->z = ccr >> 2 & 1; c->v = ccr >> 1 & 1; c->c = ccr & 1;
}

static inline void cpu_set_sr(Cpu68k *c, uint32_t sr)
{
    uint8_t new_s = sr >> 13 & 1;
    if (new_s != c->s) {                       /* mode change: swap the stack pointers */
        if (new_s) { c->usp = c->a[7]; c->a[7] = c->ssp; }
        else       { c->ssp = c->a[7]; c->a[7] = c->usp; }
        c->s = new_s;
    }
    c->t = sr >> 15 & 1;
    c->imask = sr >> 8 & 7;
    cpu_set_ccr(c, sr);
}

/* ------------------------------------------------------------------ exceptions */
/* 68000 group 1/2 exception (TRAP, divide by zero, CHK, TRAPV, privilege, illegal):
 * switches to supervisor, pushes PC and SR (6 bytes) and jumps to the vector. */
static inline void cpu_exception(Cpu68k *c, int vector, uint32_t return_pc)
{
    uint32_t sr = cpu_get_sr(c);
    if (!c->s) { c->usp = c->a[7]; c->a[7] = c->ssp; c->s = 1; }
    c->t = 0;
    c->a[7] -= 4; bus_w32(c->a[7], return_pc);
    c->a[7] -= 2; bus_w16(c->a[7], sr);
    c->pc = bus_r32((uint32_t)vector * 4);
}

/* ------------------------------------------------------------------ sizes */
#define MASK_B 0xFFu
#define MASK_W 0xFFFFu
#define MASK_L 0xFFFFFFFFu
#define MSB_B 0x80u
#define MSB_W 0x8000u
#define MSB_L 0x80000000u

static inline uint32_t sext8(uint32_t v)  { return (uint32_t)(int32_t)(int8_t)v; }
static inline uint32_t sext16(uint32_t v) { return (uint32_t)(int32_t)(int16_t)v; }

/* Writes only the bits of the operation size into a data register. */
static inline void set_d(Cpu68k *c, int r, uint32_t v, uint32_t mask) { c->d[r] = (c->d[r] & ~mask) | (v & mask); }

/* N and Z of a result of the given size. */
static inline void flags_nz(Cpu68k *c, uint32_t r, uint32_t mask, uint32_t msb)
{
    c->n = (r & msb) != 0;
    c->z = (r & mask) == 0;
}

/* ------------------------------------------------------------------ operations */
/* Each operation takes the already-read operands, returns the result (without writing it)
 * and updates the flags exactly like the 68000. */

/* MOVE, MOVEQ, TST, CLR, AND/OR/EOR, NOT: N and Z from the result; V = C = 0; X untouched. */
static inline uint32_t op_logic(Cpu68k *c, uint32_t r, uint32_t mask, uint32_t msb)
{
    flags_nz(c, r, mask, msb);
    c->v = 0; c->c = 0;
    return r & mask;
}

/* ADD / ADDI / ADDQ (not to an address register). */
static inline uint32_t op_add(Cpu68k *c, uint32_t s, uint32_t d, uint32_t mask, uint32_t msb)
{
    uint32_t r = (d + s) & mask;
    s &= mask; d &= mask;
    flags_nz(c, r, mask, msb);
    c->v = ((s ^ r) & (d ^ r) & msb) != 0;
    c->c = c->x = (((s & d) | (~r & (s | d))) & msb) != 0;
    return r;
}

/* SUB / SUBI / SUBQ: d - s. */
static inline uint32_t op_sub(Cpu68k *c, uint32_t s, uint32_t d, uint32_t mask, uint32_t msb)
{
    uint32_t r = (d - s) & mask;
    s &= mask; d &= mask;
    flags_nz(c, r, mask, msb);
    c->v = ((s ^ d) & (r ^ d) & msb) != 0;
    c->c = c->x = (((s & ~d) | (r & ~d) | (s & r)) & msb) != 0;
    return r;
}

/* CMP / CMPI / CMPA: like SUB but with no result and no X. */
static inline void op_cmp(Cpu68k *c, uint32_t s, uint32_t d, uint32_t mask, uint32_t msb)
{
    uint32_t r = (d - s) & mask;
    s &= mask; d &= mask;
    flags_nz(c, r, mask, msb);
    c->v = ((s ^ d) & (r ^ d) & msb) != 0;
    c->c = (((s & ~d) | (r & ~d) | (s & r)) & msb) != 0;
}

/* ADDX: d + s + X. Z is only cleared if the result is non-zero (never set). */
static inline uint32_t op_addx(Cpu68k *c, uint32_t s, uint32_t d, uint32_t mask, uint32_t msb)
{
    uint32_t r = (d + s + c->x) & mask;
    s &= mask; d &= mask;
    c->n = (r & msb) != 0;
    if (r) c->z = 0;
    c->v = ((s ^ r) & (d ^ r) & msb) != 0;
    c->c = c->x = (((s & d) | (~r & (s | d))) & msb) != 0;
    return r;
}

/* SUBX: d - s - X. */
static inline uint32_t op_subx(Cpu68k *c, uint32_t s, uint32_t d, uint32_t mask, uint32_t msb)
{
    uint32_t r = (d - s - c->x) & mask;
    s &= mask; d &= mask;
    c->n = (r & msb) != 0;
    if (r) c->z = 0;
    c->v = ((s ^ d) & (r ^ d) & msb) != 0;
    c->c = c->x = (((s & ~d) | (r & ~d) | (s & r)) & msb) != 0;
    return r;
}

/* NEG: 0 - d. */
static inline uint32_t op_neg(Cpu68k *c, uint32_t d, uint32_t mask, uint32_t msb)
{
    return op_sub(c, d, 0, mask, msb);
}

/* NEGX: 0 - d - X. */
static inline uint32_t op_negx(Cpu68k *c, uint32_t d, uint32_t mask, uint32_t msb)
{
    return op_subx(c, d, 0, mask, msb);
}

/* ------------------------------------------------------------------ shifts */
enum { SH_AS, SH_LS, SH_ROX, SH_RO };

/* ASx/LSx/ROXx/ROx by `cnt` positions (0-63), bit by bit: exact by definition.
 * cnt = 0: C = 0 (ROX: C = X), X untouched, V = 0, N and Z from the operand. */
static inline uint32_t op_shift(Cpu68k *c, int kind, int left, uint32_t cnt, uint32_t v,
                                uint32_t mask, uint32_t msb)
{
    v &= mask;
    uint32_t out = 0;
    int vflag = 0;
    for (uint32_t k = 0; k < cnt; k++) {
        if (left) {
            out = v & msb;
            uint32_t in = kind == SH_RO ? (out != 0) : kind == SH_ROX ? c->x : 0;
            uint32_t nv = ((v << 1) | in) & mask;
            if (kind == SH_AS && ((nv ^ v) & msb)) vflag = 1;   /* the MSB changed at some step */
            v = nv;
        } else {
            out = v & 1;
            uint32_t in = kind == SH_AS ? (v & msb)
                        : kind == SH_RO ? (out ? msb : 0)
                        : kind == SH_ROX ? (c->x ? msb : 0) : 0;
            v = (v >> 1) | in;
        }
        if (kind == SH_ROX) c->x = out != 0;
    }
    if (cnt == 0) {
        c->c = kind == SH_ROX ? c->x : 0;
    } else {
        c->c = out != 0;
        if (kind == SH_AS || kind == SH_LS) c->x = c->c;
    }
    c->v = (uint8_t)vflag;
    flags_nz(c, v, mask, msb);
    return v;
}

/* ------------------------------------------------------------------ MUL cycles */
/* Extra 68000 cycles in MULU/MULS (the base cost is already in the per-opcode table):
 * MULU adds 2 for each 1 bit of the source operand; MULS, 2 for each 0->1 or 1->0 transition
 * walking the sign-extended operand. Same as Musashi 4.60 for the 68000. */
static inline int cycles_mulu(uint32_t s)
{
    int n = 0;
    for (uint32_t y = s & 0xFFFF; y; y >>= 1) n += (y & 1) * 2;
    return n;
}

/* MULS: 2 cycles for each 01/10 pair in the 17-bit source (the word with a 0 appended as the
 * least significant bit), per the 68000 manual; verified against MAME (Phase 4). */
static inline int cycles_muls(uint32_t s)
{
    uint32_t t = ((s << 1) ^ s) & 0xFFFF;
    int n = 0;
    for (; t; t &= t - 1) n += 2;
    return n;
}

/* ------------------------------------------------------------------ division */
/* DIVU.W: d[r] (32 bits) / s (16 bits, non-zero). Overflow: only V = 1 and the register
 * is unchanged (N and Z keep their values: undefined in the manual; this is what Musashi does,
 * still to be confirmed against MAME). C = 0 if there is no overflow. */
static inline void op_divu(Cpu68k *c, int r, uint32_t s)
{
    uint32_t q = c->d[r] / s, rem = c->d[r] % s;
    if (q > 0xFFFF) { c->v = 1; return; }
    c->d[r] = (q & 0xFFFF) | rem << 16;
    c->n = (q & 0x8000) != 0; c->z = q == 0; c->v = 0; c->c = 0;
}

/* Signed DIVS.W. 0x80000000 / -1 overflows (V = 1) as on the hardware. */
static inline void op_divs(Cpu68k *c, int r, uint32_t s)
{
    int32_t dividend = (int32_t)c->d[r], divisor = (int16_t)s;
    if (dividend == INT32_MIN && divisor == -1) { c->v = 1; return; }
    int32_t q = dividend / divisor, rem = dividend % divisor;
    if (q < -32768 || q > 32767) { c->v = 1; return; }
    c->d[r] = ((uint32_t)q & 0xFFFF) | (uint32_t)rem << 16;
    c->n = (q & 0x8000) != 0; c->z = (q & 0xFFFF) == 0; c->v = 0; c->c = 0;
}

/* ------------------------------------------------------------------ BCD */
/* ABCD / SBCD: result, C, X and Z per the manual (Z is only cleared). N and V are undefined in
 * the manual; the Musashi 4.60 formulas (MIT, Karl Stenerud) are reproduced until they are
 * confirmed against MAME. */
static inline uint32_t op_abcd(Cpu68k *c, uint32_t s, uint32_t d)
{
    uint32_t res = (s & 0x0F) + (d & 0x0F) + c->x;
    uint32_t v = ~res;
    if (res > 9) res += 6;
    res += (s & 0xF0) + (d & 0xF0);
    c->c = c->x = res > 0x99;
    if (c->c) res -= 0xA0;
    c->v = ((v & res) & 0x80) != 0;
    c->n = (res & 0x80) != 0;
    res &= 0xFF;
    if (res) c->z = 0;
    return res;
}

static inline uint32_t op_sbcd(Cpu68k *c, uint32_t s, uint32_t d)
{
    uint32_t res = (d & 0x0F) - (s & 0x0F) - c->x;
    uint32_t v = ~res;
    if (res > 9) res -= 6;
    res += (d & 0xF0) - (s & 0xF0);
    c->c = c->x = res > 0x99;
    if (c->c) res += 0xA0;
    res &= 0xFF;
    c->v = ((v & res) & 0x80) != 0;
    c->n = (res & 0x80) != 0;
    if (res) c->z = 0;
    return res;
}

/* ------------------------------------------------------------------ conditions */
/* 68000 condition codes (Bcc, Scc, DBcc). */
enum { CC_T, CC_F, CC_HI, CC_LS, CC_CC, CC_CS, CC_NE, CC_EQ,
       CC_VC, CC_VS, CC_PL, CC_MI, CC_GE, CC_LT, CC_GT, CC_LE };

static inline bool cond(const Cpu68k *c, int cc)
{
    switch (cc) {
    case CC_T:  return true;
    case CC_F:  return false;
    case CC_HI: return !c->c && !c->z;
    case CC_LS: return c->c || c->z;
    case CC_CC: return !c->c;
    case CC_CS: return c->c;
    case CC_NE: return !c->z;
    case CC_EQ: return c->z;
    case CC_VC: return !c->v;
    case CC_VS: return c->v;
    case CC_PL: return !c->n;
    case CC_MI: return c->n;
    case CC_GE: return c->n == c->v;
    case CC_LT: return c->n != c->v;
    case CC_GT: return !c->z && c->n == c->v;
    default:    return c->z || c->n != c->v;   /* CC_LE */
    }
}

#endif
